using Azure.Storage.Blobs;
using Azure.Identity;

var blobServiceClient = new BlobServiceClient(
  new Uri("https://stdemostorage.blob.core.windows.net"),
  new DefaultAzureCredential());

var containerClient = blobServiceClient.GetBlobContainerClient("uploads");
await containerClient.CreateIfNotExistsAsync();

var blobClient = containerClient.GetBlobClient("report.pdf");
await blobClient.UploadAsync("./report.pdf", overwrite: true);
Console.WriteLine("Upload complete: " + blobClient.Uri);

await blobClient.DownloadToAsync("./report-copy.pdf");
Console.WriteLine("Download complete");

await foreach (BlobItem blobItem in containerClient.GetBlobsAsync())
{
  Console.WriteLine($"{blobItem.Name} — {blobItem.Properties.ContentLength} bytes");
}

var blobClient = containerClient.GetBlobClient("index.html");
var uploadOptions = new BlobUploadOptions
{
  HttpHeaders = new BlobHttpHeaders { ContentType = "text/html" }
};
await blobClient.UploadAsync("./index.html", uploadOptions);
